NG</span></div><div class="career-actions"><button class="button primary" id="careerRace">RACE THE NEXT ROUND <span>↗</span></button><button class="button ghost" id="eraAdvance">${career.unlocked>career.era?'ENTER '+next.short:'ERA '+String(career.era+1).padStart(2,'0')+' OF 09'}</button></div></div><div class="data-panel"><h3>DRIVER DOSSIER</h3><p style="font-size:10px;color:#aab1a2;line-height:1.8">You arrived with no name, no contract, and everything to prove. Race clean, find pace, and the paddock will start to notice.</p><div class="schedule-row"><span class="round-num">◈</span><div class="row-main"><b>${career.starts} Grand Prix starts</b><small>WORLD CHAMPIONSHIP</small></div></div><div class="schedule-row"><span class="round-num">✦</span><div class="row-main"><b>${career.podiums} podiums · ${career.championships} titles</b><small>CAREER HONOURS</small></div></div><div class="schedule-row"><span class="round-num">¤</span><div class="row-main"><b>${career.credits} development credits</b><small>AVAILABLE FOR R&D</small></div></div><div class="schedule-row"><span class="round-num">◷</span><div class="row-main"><b>${career.bestLap||'No lap set yet'}</b><small>PERSONAL BEST LAP</small></div></div><div class="career-actions"><button class="button ghost" id="renameDriver">EDIT DRIVER NAME</button><button class="button ghost" id="resetCareer">RESET CAREER</button></div></div></div></div>`;$('#careerRace').onclick=()=>startCareerRace();$('#eraAdvance').onclick=()=>{if(career.unlocked>career.era){career.era++;career.round=0;save();renderCareer();updateProfile();toast(`Welcome to ${ERAS[career.era].name}`)}else toast('Win a three-round season to unlock the next generation')};$('#renameDriver').onclick=()=>{const name=prompt('Choose your driver name (up to 12 characters):',career.driver);if(name&&name.trim()){career.driver=name.trim().toUpperCase().slice(0,12);save();renderCareer();updateProfile()}};$('#resetCareer').onclick=()=>{if(confirm('Reset your driver career and all development?')){localStorage.removeItem('f1-generations-career');career={driver:'ROOKIE',rep:12,credits:250,era:0,round:0,wins:0,podiums:0,starts:0,championships:0,upgrades:{},unlocked:0,bestLap:null,champRound:0,champPoints:0};selectedEra=0;save();renderCareer();populateEra();toast('A fresh start. Your legend begins now.')}}}

