function bindControls(){window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();keys[key]=true;if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(key))e.preventDefault();if(key==='p'&&game)requestPit();if(key==='c'&&game)cycleCamera();if(key==='escape'&&game)pauseGame()},{passive:false});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});$$('.mobile-controls button').forEach(button=>{const control=button.dataset.control;const down=e=>{e.preventDefault();touchControls[control]=true};const up=e=>{e.preventDefault();touchControls[control]=false};button.addEventListener('pointerdown',down);['pointerup','pointercancel','pointerleave'].forEach(type=>button.addEventListener(type,up))});window.addEventListener('resize',()=>{if(game)resizeCanvas()})}
function startCareerRace(){const round=career.round%TRACKS.length;selectedEra=career.era;selectedTrack=round;startSession('race',round,career.era,true)}
function startSession(mode,trackIndex,eraIndex,fromCareer=false){if(game)cancelAnimationFrame(game.raf);selectedEra=clamp(eraIndex,0,8);selectedTrack=clamp(trackIndex,0,TRACKS.length-1);const track=TRACKS[selectedTrack],era=ERAS[selectedEra];if(!track.era.includes(selectedEra)){toast('That circuit is not available in this generation.');return}const laps=mode==='qualifying'?1:mode==='practice'?2:mode==='timetrial'?2:3;const upgrades=career.upgrades||{};const power=era.power+Math.min(12,(upgrades.engine||0)*2)+(selectedEra>=3?Math.min(5,(upgrades.turbo||0)):0);const grip=era.grip+Math.min(13,(upgrades.aero||0)*2)+(upgrades.suspension||0);const player={distance:0,lateral:0,speed:0,damage:0,tyre:100,fuel:Math.max(14,laps*track.len/100),engineTemp:88,condition:100,boost:100,steer:0,lapTime:0,bestLap:Infinity,lapStart:0,gear:1,offroad:0,skid:0};const ai=Array.from({length:7},(_,i)=>({id:i,distance:-((7-i)*27+Math.random()*18),lateral:(Math.random()-.5)*.8,speed:era.max*(.57+Math.random()*.06),pace:.95+Math.random()*.11,color:['#e44735','#e5e6da','#48a9c1','#e6b640','#54a879','#e1e2d9','#db6b43'][i]}));game={mode,fromCareer,trackIndex:selectedTrack,eraIndex:selectedEra,track,era,laps,player,ai,running:true,started:false,paused:false,countdown:3.7,lights:0,weather:'DRY',tyre:'SOFT',camera:0,pitRequested:false,pitTimer:0,damageTimer:0,elapsed:0,sessionTime:0,raf:0,view:{w:0,h:0,dpr:1},messageTimer:0,seed:Math.random()*100,sessionLabel:{race:'RACE DAY',practice:'PRACTICE 1',qualifying:'QUALIFYING',championship:'CHAMPIONSHIP',timetrial:'TIME TRIAL'}[mode]||'RACE DAY',power,grip};$('#raceScreen').classList.remove('hidden');$('#pauseModal').classList.add('hidden');$('#resultModal').classList.add('hidden');$('#countdownLights').classList.remove('hidden');$('#countdownLights').classList.remove('lit','go');$('#raceTitle').textContent=`${track.name.toUpperCase()} GRAND PRIX`;$('#raceRound').textContent=fromCareer?`ROUND ${String(career.round+1).padStart(2,'0')}`:'GRAND PRIX';$('#raceSubtitle').textContent=`${era.year} · ${game.sessionLabel}`;$('#lapValue').innerHTML=`01<span>/${String(laps).padStart(2,'0')}</span>`;$('#positionValue').textContent='P 08';$('#tyreValue').textContent='SOFT · 100%';$('#fuelValue').textContent=`${Math.round(player.fuel)} L`;$('#engineValue').textContent='88°';$('#conditionValue').textContent='100%';$('#cameraButton').innerHTML='CAM <b>CHASE</b>';$('#weatherButton').innerHTML='WEATHER <b>DRY</b>';$('#tyreButton').innerHTML='TYRE <b>SOFT</b>';$('#pitButton').innerHTML='PIT <b>REQUEST</b>';message('GET READY');resizeCanvas();frameLast=performance.now();game.raf=requestAnimationFrame(raceFrame);if(soundOn)startAudio()}
function resizeCanvas(){if(!game)return;const canvas=$('#raceCanvas'),dpr=Math.min(window.devicePixelRatio||1,2),rect=canvas.getBoundingClientRect();canvas.width=Math.floor(rect.width*dpr);canvas.height=Math.floor(rect.height*dpr);game.view={w:rect.width,h:rect.height,dpr};const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0)}
function message(text){const node=$('#raceMessage');node.textContent=text;node.classList.add('show');if(game)game.messageTimer=1.5}
function pauseGame(){if(!game||game.paused)return;game.paused=true;$('#pauseModal').classList.remove('hidden');stopAudio()}
function resumeGame(){if(!game)return;game.paused=false;$('#pauseModal').classList.add('hidden');frameLast=performance.now();if(soundOn)startAudio();game.raf=requestAnimationFrame(raceFrame)}
function leaveRace(){if(game)cancelAnimationFrame(game.raf);game=null;stopAudio();$('#raceScreen').classList.add('hidden');$('#pauseModal').classList.add('hidden');$('#resultModal').classList.add('hidden');$('#countdownLights').classList.add('hidden');if(activePage==='career')renderCareer();if(activePage==='garage')renderGarage();updateProfile()}
function cycleCamera(){if(!game)return;game.camera=(game.camera+1)%4;const names=['CHASE','COCKPIT','TV','TRACKSIDE'];$('#cameraButton').innerHTML=`CAM <b>${names[game.camera]}</b>`;toast(`${names[game.camera]} CAMERA`)}
function toggleWeather(){if(!game)return;game.weather=game.weather==='DRY'?'WET':'DRY';$('#weatherButton').innerHTML=`WEATHER <b>${game.weather}</b>`;message(game.weather==='WET'?'RAIN ON TRACK':'TRACK DRYING');if(game.weather==='WET'&&game.tyre==='SOFT')toast('Wet grip reduced — request INTERS or WETS')}
function cycleTyre(){if(!game)return;const names=['SOFT','MEDIUM','HARD','INTER'];game.tyre=names[(names.indexOf(game.tyre)+1)%names.length];$('#tyreButton').innerHTML=`TYRE <b>${game.tyre}</b>`;toast(`${game.tyre} COMPOUND SELECTED`)}
function requestPit(){if(!game)return;if(game.pitTimer>0){toast('Pit stop already in progress');return}if(Math.abs(game.player.lateral)>.65){toast('Stay on track to enter the pit lane');return}game.pitRequested=true;$('#pitButton').innerHTML='PIT <b>IN THIS LAP</b>';message('PIT STOP REQUESTED')}
function raceFrame(now){if(!game||game.paused)return;const dt=Math.min(.05,Math.max(0,(now-frameLast)/1000));frameLast=now;updateRace(dt);drawRace();if(game&&game.running)game.raf=requestAnimationFrame(raceFrame)}

