 const throttle=keys.w||keys.arrowup||touchControls.gas,brake=keys.s||keys.arrowdown||touchControls.brake,left=keys.a||keys.arrowleft||touchControls.left,right=keys.d||keys.arrowright||touchControls.right;const steer=(right?1:0)-(left?1:0);p.steer+=(steer-p.steer)*Math.min(1,dt*5);const wet=g.weather==='WET'?0.77:1,compound={SOFT:1,MEDIUM:.92,HARD:.82,INTER:.78}[g.tyre]||1,grip=clamp((g.grip/70)*wet*compound*(1-p.damage*.006),.35,1.35);let target=g.era.max*(throttle?1:.32);if(!throttle&&p.speed>55)target=Math.max(0,p.speed-30);if(brake)target=0;p.speed+=clamp(target-p.speed,-(brake?g.era.braking*3.1:42)*dt,(g.era.accel*2.7)*dt);if(Math.abs(p.steer)>.2&&p.speed>g.era.max*.62){p.speed=Math.max(0,p.speed-(Math.abs(p.steer)*7/grip)*dt);p.skid=Math.min(1,p.skid+dt*.6)}else p.skid=Math.max(0,p.skid-dt);const oldDistance=p.distance;p.distance+=p.speed/3.6*dt;p.lapTime+=dt;p.lateral=clamp(p.lateral+p.steer*dt*(.65+p.speed/g.era.max*.7),-1.25,1.25);if(Math.abs(p.lateral)>.86){p.offroad+=dt;p.speed=Math.max(0,p.speed-(20+Math.abs(p.lateral)*15)*dt);p.tyre=Math.max(0,p.tyre-dt*.24);if(p.offroad>1.3&&Math.random()<dt*1.6){p.damage=Math.min(75,p.damage+2);message('GRAVEL — CAR DAMAGE')}}else p.offroad=Math.max(0,p.offroad-dt*1.4);p.tyre=Math.max(0,p.tyre-dt*g.era.wear*(g.tyre==='SOFT'?1.5:g.tyre==='HARD'?.65:1)*(p.speed/g.era.max)*.24);p.fuel=Math.max(0,p.fuel-dt*(.05+p.speed/g.era.max*.08));p.engineTemp=clamp(p.engineTemp+dt*((throttle?4:0)-(p.speed<80?2:0)),72,132);if(p.engineTemp>120)p.condition=Math.max(20,p.condition-dt*.5);p.gear=clamp(Math.floor(p.speed/48)+1,1,8);p.boost=clamp(p.boost+dt*(g.era.year>=2009?(throttle?-6:4):0),0,100);if(p.fuel<=0){p.speed=Math.max(0,p.speed-20*dt);message('OUT OF FUEL')}
 const lapNow=Math.floor(p.distance/g.track.len);if(lapNow>g.completedLaps){g.completedLaps=lapNow;const lap=p.lapTime;p.bestLap=Math.min(p.bestLap,lap);p.lapTime=0;$('#lapValue').innerHTML=`${Math.min(g.laps,lapNow+1).toString().padStart(2,'0')}<span>/${String(g.laps).padStart(2,'0')}</span>`;if(lapNow<g.laps){message(`LAP ${lapNow+1} · ${fmtTime(lap)}`);if(g.pitRequested){g.pitRequested=false;g.pitTimer=4.2;p.speed=0;message('PIT STOP — TYRES & FUEL');$('#pitButton').innerHTML='PIT <b>REQUEST</b>'}}else finishSession()}
