function finishSession(){if(!game||!game.running)return;const g=game,p=g.player;g.running=false;const order=[{distance:p.distance,player:true},...g.ai].sort((a,b)=>b.distance-a.distance),place=order.findIndex(x=>x.player)+1;$('#countdownLights').classList.add('hidden');$('#resultModal').classList.remove('hidden');$('#resultTitle').textContent=place===1?'VICTORY — THE FLAG IS YOURS':place<=3?'PODIUM FINISH':place===8?'CHEQUERED FLAG':'A HARD-FOUGHT FINISH';$('#resultCopy').textContent=`${g.track.name} · ${g.era.year} generation · ${g.laps} laps. ${place===1?'A commanding drive from lights to flag.':'You brought it home in P'+String(place)+'.'}`;$('#resultPosition').textContent=`P ${String(place).padStart(2,'0')}`;$('#resultTime').textContent=Number.isFinite(p.bestLap)?fmtTime(p.bestLap):fmtTime(p.lapTime);const repGain=Math.max(4,22-place*2+Math.round(p.condition/20));$('#resultXP').textContent=`+${repGain}`;$('#podiumCars').innerHTML=g.ai.slice(0,3).map((car,i)=>`<span style="--car-color:${car.color}">${i+2}</span>`).join('');if(g.fromCareer||g.mode==='championship'){career.starts++;career.rep=clamp(career.rep+repGain,0,100);career.credits+=Math.max(30,150-place*12);if(place===1)career.wins++;if(place<=3)career.podiums++;career.champPoints+=([25,18,15,12,10,8,6,4][place-1]||0);career.bestLap=fmtTime(p.bestLap||p.lapTime);career.round++;career.champRound++;if(career.champRound>=3){career.championships+=career.champPoints>=60?1:0;career.champPoints=0;career.champRound=0;if(career.wins>=2)career.unlocked=Math.max(career.unlocked,Math.min(8,career.era+1));if(career.unlocked>career.era)$('#resultCopy').textContent+=' A new generation is unlocked in your career.'}save();updateProfile()}stopAudio()}
function drawRace(){const g=game;if(!g)return;const canvas=$('#raceCanvas'),ctx=canvas.getContext('2d'),w=g.view.w,h=g.view.h;if(!w||!h)return;const horizon=h*.38,player=g.player,era=g.era;const sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,g.weather==='WET'?'#65757a':'#93b7bd');sky.addColorStop(1,g.weather==='WET'?'#8a9490':'#e0c999');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);ctx.fillStyle=g.track.color;ctx.fillRect(0,horizon,w,h-horizon);for(let i=0;i<45;i++){const x=((i*197+g.seed*71)%w),y=horizon+((i*97+g.seed*31)%(h-horizon));ctx.fillStyle=i%3?'rgba(26,45,28,.26)':'rgba(217,207,158,.18)';ctx.fillRect(x,y,2+(i%4),2+(i%3))}ctx.fillStyle='#66716c';ctx.fillRect(0,horizon-12,w,12);const strips=64,roadW=w*.49;let prevL=null,prevR=null;for(let i=0;i<=strips;i++){const depth=i/strips, y=horizon+Math.pow(depth,1.56)*(h-horizon),look=(1-depth)*940,phase=(player.distance+look)/g.track.len*Math.PI*2*g.track.shape,curve=Math.sin(phase)*w*.12+Math.sin(phase*.47+1.6)*w*.05,center=w*.5+curve-player.steer*10,half=roadW*(.18+Math.pow(depth,1.2)*.82);const left=center-half,right=center+half;if(prevL){ctx.fillStyle=i%2?'#4b4d48':'#555650';ctx.beginPath();ctx.moveTo(prevL[0],prevL[1]);ctx.lineTo(prevR[0],prevR[1]);ctx.lineTo(right,y);ctx.lineTo(left,y);ctx.closePath();ctx.fill();const curbW=half*.075;ctx.fillStyle=i%2?'#e9eee2':'#cf4937';ctx.fillRect(left-curbW,y,curbW*1.8,Math.max(2,(h-horizon)/strips*2));ctx.fillRect(right-curbW*.8,y,curbW*1.8,Math.max(2,(h-horizon)/strips*2));if(Math.floor((g.elapsed*12+i)/3)%2===0){ctx.strokeStyle='rgba(236,232,208,.42)';ctx.lineWidth=Math.max(.5,depth*2);ctx.beginPath();ctx.moveTo(center,y);ctx.lineTo((prevL[0]+prevR[0])/2,(prevL[1]+prevR[1])/2);ctx.stroke()}}prevL=[left,y];prevR=[right,y]}
 ctx.fillStyle='rgba(12,18,16,.22)';ctx.fillRect(0,horizon,w,2);g.ai.forEach(car=>{const rel=car.distance-player.distance;if(rel< -100||rel>650)return;const d=1-clamp(rel/650,0,1),y=horizon+Math.pow(d,1.65)*(h-horizon)*.86,scale=.18+d*.9,x=w*.5+Math.sin((player.distance+rel)/g.track.len*Math.PI*2*g.track.shape)*w*.12+car.lateral*w*.11;drawCar(ctx,x,y,scale,car.color,era.style,false)});const carY=h*.82,carX=w*.5+player.lateral*w*.24;drawCar(ctx,carX,carY,1.05,era.colors[0],era.style,true);if(g.weather==='WET'){ctx.fillStyle='rgba(95,125,147,.14)';ctx.fillRect(0,0,w,h)}if(g.camera===1){ctx.fillStyle='rgba(8,12,10,.35)';ctx.fillRect(w*.34,h*.76,w*.32,h*.24);ctx.fillStyle='#bbb';ctx.fillRect(w*.47,h*.79,w*.06,h*.03)}}
