input.newString:
export function buildTrees(layout, count = 680) {
  const rnd = mulberry32(hashStr('trees' + layout.length));
  const trunks = [], broad = [], broad2 = [], conifer = [];
  let tries = 0;
  while (trunks.length < count && tries < count * 9) {
    tries++;
    const s = layout.samples[(rnd() * layout.S) | 0];
    const sideSign = rnd() > .5 ? 1 : -1;
    const off = sideSign * (14 + rnd() * 105);
    const p = s.pos.clone().addScaledVector(s.side, off).addScaledVector(s.tangent, (rnd() - .5) * 46);
    if (layout.nearest(p.x, p.z).dist < 12.5) continue;
    const y = layout.heightAt(p.x, p.z);
    const isConifer = rnd() < .42;
    const scale = .8 + rnd() * .9;
    const trunkH = isConifer ? 2 + rnd() * 2 : 2.2 + rnd() * 2.6;
    trunks.push({ x: p.x, y, z: p.z, h: trunkH, w: .8 + rnd() * .5 });
    if (isConifer) {
      conifer.push({
        x: p.x, y: y + trunkH * .55, z: p.z,
        r: (1.5 + rnd() * 1.15) * scale, h: (6.5 + rnd() * 4.2) * scale, hue: rnd()
      });
    } else {
      const r = (2.1 + rnd() * 1.5) * scale;
      broad.push({ x: p.x, y: y + trunkH + r * .55, z: p.z, r, hue: rnd() });
      broad2.push({
        x: p.x + (rnd() - .5) * r, y: y + trunkH + r * 1.05, z: p.z + (rnd() - .5) * r,
        r: r * (.55 + rnd() * .2), hue: rnd()
      });
    }
  }

  const dummy = new THREE.Object3D();
  const col = new THREE.Color();
  const trunkGeo = new THREE.CylinderGeometry(.18, .34, 1, 5, 1);
  trunkGeo.translate(0, .5, 0);
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x53402d, roughness: 1 });
  const trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, trunks.length);
  trunks.forEach((t, i) => {
    dummy.position.set(t.x, t.y, t.z);
    dummy.rotation.set(0, t.w * 8.1, 0);
    dummy.scale.set(t.w, t.h, t.w);
    dummy.updateMatrix();
    trunkMesh.setMatrixAt(i, dummy.matrix);
  });
  trunkMesh.castShadow = true;

  const makeLeaves = (geo, list, hueShift = 0, lightness = 0) => {
    const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: .96, flatShading: true });
    const mesh = new THREE.InstancedMesh(geo, mat, list.length);
    list.forEach((t, i) => {
      dummy.position.set(t.x, t.y, t.z);
      dummy.rotation.set(0, t.hue * 6.28, 0);
      if (geo.__cone) dummy.scale.set(t.r, t.h, t.r);
      else dummy.scale.set(t.r, t.r * .88, t.r);
      dummy.updateMatrix();
      mesh.setMatrixAt(i, dummy.matrix);
      col.setHSL(.255 + hueShift + t.hue * .055, .30 + t.hue * .2, .17 + t.hue * .10 + lightness);
      mesh.setColorAt(i, col);
    });
    mesh.castShadow = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    return mesh;
  };

  const broadGeo = new THREE.IcosahedronGeometry(1, 1);
  const coneGeo = new THREE.ConeGeometry(1, 1, 7, 1);
  coneGeo.translate(0, .5, 0);
  coneGeo.__cone = true;

  const group = new THREE.Group();
  group.add(trunkMesh);
  group.add(makeLeaves(broadGeo, broad, 0, 0));
  group.add(makeLeaves(broadGeo, broad2, .02, .03));
  if (conifer.length) group.add(makeLeaves(coneGeo, conifer, -.015, -.04));
  return { group };
}

input.oldString:
export function buildTrees(layout, count = 620) {
  const rnd = mulberry32(hashStr('trees' + layout.length));
  const trunks = [], foliage = [];
  let tries = 0;
  while (trunks.length < count && tries < count * 8) {
    tries++;
    const s = layout.samples[(rnd() * layout.S) | 0];
    const sideSign = rnd() > .5 ? 1 : -1;
    const off = sideSign * (16 + rnd() * 95);
    const p = s.pos.clone().addScaledVector(s.side, off).addScaledVector(s.tangent, (rnd() - .5) * 40);
    if (layout.nearest(p.x, p.z).dist < 14) continue;
    const y = layout.heightAt(p.x, p.z);
    const h = .8 + rnd() * 1.5;
    trunks.push({ x: p.x, y, z: p.z, s: h });
    foliage.push({ x: p.x, y: y + 2.4 * h + .6, z: p.z, s: h * (1.4 + rnd() * .8), hue: rnd() });
  }
  const trunkGeo = new THREE.CylinderGeometry(.16, .3, 3, 5, 1);
  trunkGeo.translate(0, 1.5, 0);
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x4a3a2a, roughness: 1 });
  const trunkMesh = new THREE.InstancedMesh(trunkGeo, trunkMat, trunks.length);
  const dummy = new THREE.Object3D();
  trunks.forEach((t, i) => {
    dummy.position.set(t.x, t.y, t.z);
    dummy.scale.set(t.s, t.s, t.s);
    dummy.rotation.y = t.s * 4.1;
    dummy.updateMatrix();
    trunkMesh.setMatrixAt(i, dummy.matrix);
  });
  trunkMesh.castShadow = true;

  const folGeo = new THREE.ConeGeometry(2.8, 7.4, 7, 1);
  const folMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: .95, flatShading: true });
  const folMesh = new THREE.InstancedMesh(folGeo, folMat, foliage.length);
  const col = new THREE.Color();
  foliage.forEach((t, i) => {
    dummy.position.set(t.x, t.y, t.z);
    dummy.scale.set(t.s, t.s * (1.1 + t.hue * .5), t.s);
    dummy.rotation.y = t.hue * 6.28;
    dummy.updateMatrix();
    folMesh.setMatrixAt(i, dummy.matrix);
    col.setHSL(.26 + t.hue * .06, .34 + t.hue * .18, .20 + t.hue * .09);
    folMesh.setColorAt(i, col);
  });
  folMesh.castShadow = true;
  folMesh.instanceMatrix.needsUpdate = true;
  trunkMesh.instanceMatrix.needsUpdate = true;
  if (folMesh.instanceColor) folMesh.instanceColor.needsUpdate = true;
  return { group: (() => { const g = new THREE.Group(); g.add(trunkMesh, folMesh); return g; })() };
}

