285: function updateAICars(g,dt){
286:   const p=g.player;
287:   const lapLen=g.lapLength||g.track.len;
288:   g.ai.forEach((car,i)=>{
289:     const aiU=((car.distance/lapLen)%1+1)%1;
290:     let aiCap=g.era.max;
291:     if(typeof g.speedCapAt==='function')aiCap=g.speedCapAt(aiU);
292:     else{
293:       const phase=aiU*Math.PI*2*g.track.shape;
294:       aiCap=g.era.max*(.68+.32*Math.abs(Math.cos(phase)));
295:     }
296:     const targetSpeed=Math.min(g.era.max*car.pace,aiCap*car.pace)-(p.damage*.001);
297:     if(car.speed<targetSpeed){
298:       const head=clamp(1-car.speed/g.era.max,.18,1);
299:       car.speed=Math.min(targetSpeed,car.speed+g.era.accel*.9*head*dt);
300:     }else{
301:       car.speed=Math.max(targetSpeed,car.speed-(g.era.braking*1.6+(car.speed-targetSpeed)*1.1)*dt);
302:     }
303:     car.distance+=car.speed/3.6*dt;
304:     car.lateral=Math.sin(g.elapsed*.55+i*2.8)*.5;
305:   });
306: }
